import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { LoginService } from 'src/app/services/signup/login.service';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent {
  
  public form: FormGroup;

  constructor(
    private service: LoginService,
    private fb: FormBuilder,
    private router: Router)
  {
    this.form = this.fb.group({
      password: [
        '', Validators.compose([
          Validators.minLength(5),
          Validators.maxLength(50),
          Validators.required
        ])
      ],
      email: [
        '', Validators.compose([
          Validators.minLength(5),
          Validators.maxLength(150),
          Validators.required
        ])
      ],
    })
  }

  async register(){
    this.service.registerUser(this.form.value).subscribe( (data: any) => {
      this.router.navigate(['/login']);
    },
    (err) => {
      console.log(err);
    } )
  }

  login(rowdata: any){
    this.service.login(this.form.value).subscribe( (data: any) => {
      this.router.navigate(['/home']);
    },
    (err) => {
      console.log(err);
    })
  }
}
<div class="uk-flex-center" uk-grid>
  <div class="uk-width-1-3@m">
    <p class="uk-text-center uk-margin-large-top uk-margin-medium-bottom">
      <span class="uk-icon uk-margin-small-right" uk-icon="icon: logo-color-dark; ratio: 0.7"></span>
    </p>


    <form>
      <div class="uk-card uk-card-primary uk-card-body uk-box-shadow-small">
        <h3 class="uk-card-title">Autentique-se</h3>

        <div class="uk-margin">
          <input class="uk-input uk-form-large" formControlName="email" type="email" placeholder="Email">
        </div>

        <div class="uk-margin">
          <input class="uk-input uk-form-large" formControlName="password" type="password" placeholder="Senha">
        </div>

        <div class="uk-margin uk-text-right">
          <button class="uk-button uk-button-default" [routerLink]="['/home']">Entrar</button>
        </div>

      </div>
    </form>

    <p class="uk-text-center">
      <a class="uk-button uk-width-1-1 uk-button-large uk-button-primary uk-margin-small-bottom" [routerLink]="['/signup']">Cadastrar</a>
      <br>
      <a class="uk-button uk-button-link" [routerLink]="['/resetpassword']">Esqueci minha senha</a>
    </p>

  </div>
</div>
